function paragraph(b:Block){assert.equal(b.type,'paragraph');if(b.type!=='paragraph')throw Error();return b.text;}
export function autumnStackTrace(arrival:string,output:string){const stack:string[]=[],trace:{action:string;item:string;stack:string}[]=[];let cursor=0;for(const item of output){while(stack.at(-1)!==item&&cursor<arrival.length){const next=arrival[cursor++];stack.push(next);trace.push({action:'push',item:next,stack:stack.join('')});}if(stack.at(-1)!==item)return{possible:false,trace,blocked:item};stack.pop();trace.push({action:'pop',item,stack:stack.join('')});}return{possible:cursor===arrival.length&&stack.length===0,trace};}
