export function legacy2017AutumnFoundationsOracle(source:string,b:GeneratedBody,values:number[]){
 assert.match(source,/^2017h29a-fe-am-\d+$/);const n=Number(source.split('-').at(-1)),index=facts.numbers.indexOf(n),v=values[0],original=facts.originals.find(r=>r.number===n);assert(original&&index>=0);assert.equal(values.length,1);assert(Number.isInteger(v)&&v>=0&&v<facts.capacities[index]);assert.equal(b.choices.length,4);const choices=b.choices.map(c=>{assert.equal(c.length,1);return paragraph(c[0]);});assert.deepEqual(b.contexts??[],[]);assert.equal(b.answerParts,undefined);assert.equal(b.partAnswers,undefined);let truth:boolean[]=[];
 if(n===1){const target=[10,20,12,18][v];assert.equal(b.prompt.length,1);assert.equal(paragraph(b.prompt[0]),original.stem.replace('10倍',`${target}倍`));assert.deepEqual(choices,original.allFourChoices);const expressions=[(x:number)=>(x*2**2+x)*2,(x:number)=>(x*2**2+x)*2**2,(x:number)=>x*2**3+x*2**2,(x:number)=>(x*2**3+x)*2];truth=expressions.map(f=>f(1)===target);for(let x=1;x<=31;x++)assert.deepEqual(expressions.map(f=>f(x)===x*target),truth);}
 else if(n===2){assert.equal(b.prompt.length,1);assert.equal(paragraph(b.prompt[0]),facts.parity.stems[v]);assert.deepEqual(choices,facts.parity.choiceTexts);const mechanisms=['polynomial-remainder','character-unit','blocksamebitpositions','overlapping-subsets'];truth=mechanisms.map(mechanism=>mechanism===facts.parity.independentMechanismFacts[v].basis);}
 else if([3,6,7,10].includes(n)){assert.equal(b.prompt.length,1);const row=facts.knowledge.find(r=>r.number===n)!;assert.equal(paragraph(b.prompt[0]),row.stem);assert.deepEqual(choices,row.allChoices[v]);const required=({3:'actual-output-and-target-comparison',6:'self-call',7:'inherited-method-redefinition'}as Record<number,string>)[n];truth=row.roles[v].map(role=>n===10?role.startsWith('external-'):role===required);assert.deepEqual(truth,row.selectionTruth[v]);}
 else if(n===4){assert.equal(b.prompt.length,2);const stem=v===0?original.stem:original.stem.replace('比率が大きいと出力値が小さくなり、黒色に掛かる比率が小さいと出力値が大きくなる','比率が大きいと出力値が大きくなり、黒色に掛かる比率が小さいと出力値が小さくなる');assert.equal(paragraph(b.prompt[0]),stem);assert.deepEqual(choices,['ア','イ','ウ','エ']);const fig=b.prompt[1];assert(fig.type==='diagram'&&fig.scene.kind==='source_figure');if(fig.type!=='diagram'||fig.scene.kind!=='source_figure')throw Error();assert.equal(fig.scene.profile,'legacy-2017-line-following-car');assert.deepEqual(fig.scene.values,[v]);assert.equal(fig.caption,'円に沿って走る車と制御方法の解答群');assert.equal(fig.alt,autumnLineDescription(v));const observed=readAutumnLineSvg(renderToStaticMarkup(createElement(Legacy2017AutumnFoundationsFigure,{profile:fig.scene.profile,values:fig.scene.values,caption:fig.caption})),v);truth=observed.truth;}
 else if(n===5){const arrivals=['ABCD','BACD','DABC','DCAB'],arrival=arrivals[v];assert.equal(b.prompt.length,1);assert.equal(paragraph(b.prompt[0]),original.stem.replace('A、B、C、D',[...arrival].join('、')));assert.deepEqual(choices,original.allFourChoices);truth=choices.map(c=>autumnStackTrace(arrival,c.replaceAll('、','')).possible);}
 else if(n===8){assert.equal(b.prompt.length,1);assert.equal(paragraph(b.prompt[0]),facts.perl.stem);assert.deepEqual(choices,facts.perl.allFourChoicesByCondition[v]);const primary={hasWindowsProcessor:true,canExecuteCLI:true,debugLoadsInterpreterLibrary:true,userNeedsPrecompiledFile:false};truth=[!primary.hasWindowsProcessor,!primary.canExecuteCLI,!primary.debugLoadsInterpreterLibrary,!primary.userNeedsPrecompiledFile];assert.deepEqual(truth,facts.perl.truth[v]);}
 else throw Error('UNREVIEWED_SOURCE');
 assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));for(const f of explanationFacts[n][explanationFacts[n].length===1?0:v])assert(b.explanation.includes(f),`${source}/${v}: ${f}`);const frozen=contracts.records.find(r=>r.source===source)?.outputs.find(o=>o.values[0]===v);assert(frozen);assert.equal(createHash("sha256").update(b.explanation).digest("hex"),frozen.explanationSha256,"All explanation text must retain the independently reviewed mechanisms and limits");assert.doesNotMatch(b.explanation,/正答は[アイウエ]|選択肢は順に|左から[アイウエ]|生成の誤答|fixture/);return truth;
}
